import json
from typing import Union

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class AnalyticsMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.analytics.api_analytics")
    def api_analytics(
        self,
        range_: Union[list[int, int], tuple[int, int]] = (0, 9),
        sort: Union[list[str, str], tuple[str, str]] = ("name", "ASC"),
    ):
        return self.get(path="api/analytics", filter=json.dumps({}), range=range_, sort=sort)

    @tracer.start_as_current_span("admin.analytics.api_analytics_metric_name")
    def api_analytics_metric_name(self, metric_name: str, start: int, step: int):
        """
        Получение метрик по ее названию.
        :param metric_name: Название метрики из конфигурации
        :param start: Значение 'от' для диапазона выборки (timestamp)
        :param step: Значение 'шаг' для диапазона выборки
        """
        return self.get(path=f"api/analytics/{metric_name}", start=start, step=step)
